import json

from threetears.evals import Eval

from search import search

with open("data/queries.jsonl", encoding="utf-8") as queries, open("data/judgments.jsonl", encoding="utf-8") as graded:
    by_id = {row["id"]: row["query"] for row in map(json.loads, queries)}
    GRADES = {by_id[row["query_id"]]: row["grades"] for row in map(json.loads, graded)}


def ask(case):
    """The help articles the search gives for the query, best first."""
    return {"ids": [hit.id for hit in search(case["query"])]}


def best_first(case, out):
    """The first article is one the support team graded best for the query."""
    grades = GRADES[case["query"]]
    return bool(out["ids"]) and grades.get(out["ids"][0], 0) == max(grades.values())


queries = Eval("data/queries.jsonl", runner=ask, grader=[best_first], k=1)
